export function Padding({
  top = {{top}},
  right = {{right}},
  bottom = {{bottom}},
  left = {{left}},
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A blush padding layer between an element's border and its content, sized independently on each side">
      <div style={{ background: "#F5C2E0", borderRadius: 8, boxSizing: "border-box", padding: `${top}px ${right}px ${bottom}px ${left}px` }}>
        <div style={{ background: "#A8E6C1", borderRadius: 6, padding: 10, fontWeight: 700, textAlign: "center" }}>content</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>padding: {top}px {right}px {bottom}px {left}px (top right bottom left)</p>
    </div>
  );
}
